-- 영문판(/en/) 표시값 칸.
--
-- 영문판은 필름 카탈로그·현상소·수리실을 같은 테이블에서 읽는다. 공개 화면이 DB 를 먼저 읽으므로
-- 번역을 정적 JSON 에만 두면 보이지 않는다. 그래서 원본 테이블에 영문 칸을 둔다.
-- 비어 있으면 화면은 한국어 원문을 보여 준다.
--
-- labs·repair_shops 의 name·region·address 원문은 그대로 둔다. 지역 필터·딥링크 슬러그·네이버 지도 검색이
-- 한국어 값을 키로 쓰기 때문이다. 영문 칸은 화면 표시에만 쓴다.

ALTER TABLE public.films        ADD COLUMN IF NOT EXISTS description_en text;

ALTER TABLE public.labs         ADD COLUMN IF NOT EXISTS name_en text;
ALTER TABLE public.labs         ADD COLUMN IF NOT EXISTS address_en text;
ALTER TABLE public.labs         ADD COLUMN IF NOT EXISTS features_en text;

ALTER TABLE public.repair_shops ADD COLUMN IF NOT EXISTS name_en text;
ALTER TABLE public.repair_shops ADD COLUMN IF NOT EXISTS address_en text;
ALTER TABLE public.repair_shops ADD COLUMN IF NOT EXISTS specialty_en text;
ALTER TABLE public.repair_shops ADD COLUMN IF NOT EXISTS description_en text;

-- ── 번역 채우기 (2026-10-01, AI 번역) ──
-- 영문 칸이 비어 있는 행만 채운다. 관리 화면에서 나중에 고친 값은 다시 적용해도 덮지 않는다.
-- 관리 화면에서만 등록돼 저장소 사본에 없는 행은 여기서 채우지 못한다(관리 화면 영문 칸에 입력).

-- 필름 소개글 161종
UPDATE public.films SET description_en = $en$An ISO 400 color negative that handles everything from indoor light to bright sunshine on a single roll. C-41 process. It comes in 24-exposure rolls, so it's an easy, low-commitment everyday pick.$en$ WHERE slug = '1shot400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Fujifilm's first-generation Acros, discontinued in 2018. With extremely fine grain, rich tonal gradation, and almost no reciprocity failure for exposures up to 14 minutes, it marked a high point for Japanese black-and-white film. Its legacy lives on today in Acros II.$en$ WHERE slug = 'acros1' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The relaunched version of Fujifilm Acros. Very fine, precise grain and clean tones define it, and it's widely regarded as the benchmark Japanese black-and-white film. Its near-total lack of reciprocity failure on long exposures is another big plus.$en$ WHERE slug = 'acros2' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A re-release of Adox's traditional black-and-white film. Pronounced grain and a classic tonal curve give it a vintage monochrome mood.$en$ WHERE slug = 'adoxchs100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Adox's ultra-high-resolution black-and-white film. Microfine grain and a rich range of grays make it shine for landscapes and big enlargements.$en$ WHERE slug = 'adoxhr50' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Adox's color line, launched in 2023. Natural color and fine grain make it a fresh arrival in the entry-level color market.$en$ WHERE slug = 'adoxmission200' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A specialty film that rebrands Kodak's aerial survey color stock for still photography. Expect soft color, fine grain, and very wide latitude. It's respooled and sold under several brands, including Reflx Lab and FlicFilm.$en$ WHERE slug = 'aerocolor' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Agfa's slow black-and-white film. The sister to APX 400, with finer, more precise grain, it's the one to reach for when you want smooth monochrome in landscapes and still lifes. A re-release under the AgfaPhoto brand.$en$ WHERE slug = 'agfaapx100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The current version of Agfa's classic black-and-white film. Since its 2017 relaunch under the AgfaPhoto brand, its deep contrast and bold grain have made it a familiar sight in documentary and street work.$en$ WHERE slug = 'agfaapx400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Agfa's everyday color slide (E-6) film. Saturated color and rich detail made it a regular for landscape and travel shooting, and in its later years it was a repackaged Fuji emulsion. Now discontinued.$en$ WHERE slug = 'agfactprecisa100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The only black-and-white slide film ever sold commercially. It develops to a positive rather than a negative, so you can lay it on a lightbox and see the image as is. It required its own AP-44 process, which meant sending it to designated labs. Grain is very fine and blacks are deep, though it has a reputation for thin midtones. Rated at ISO 200, it could be shot anywhere from 100 to 1600. Discontinued in 2005.$en$ WHERE slug = 'agfascala200x' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Agfa's high-saturation professional color negative. Rich color and deep shadow detail kept it in steady use for landscapes and portraits. It was discontinued around 2018, alongside the Vista line.$en$ WHERE slug = 'agfaultra100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The slow-speed color negative in Agfa's Vista line. Gentle contrast and natural skin tones made it a steady choice for everyday snapshots and outdoor color prints. Discontinued in 2018 along with Vista 200 and 400.$en$ WHERE slug = 'agfavista100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Agfa's everyday color negative. A faint magenta cast and restrained saturation made it a reliable, budget-friendly film for daily life. Discontinued in 2018, it now trades among collectors.$en$ WHERE slug = 'agfavista200' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The faster sibling in Agfa's Vista line. Slightly coarser grain than Vista 200 and cooler, crisper color made it strong on overcast days and for everyday indoor shooting. Discontinued in 2018.$en$ WHERE slug = 'agfavista400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A black-and-white film that Freestyle in the US sells as a rebrand of Czech maker Foma's Fomapan 100. The emulsion is the same as Fomapan 100, and it sells for less in North America. Great for shooting plenty of black-and-white on a budget.$en$ WHERE slug = 'aristaedu100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A black-and-white film that Freestyle in the US sells as a rebrand of Czech maker Foma's Fomapan 200. The emulsion is the same as Fomapan 200, and it sells for less in North America. Great for shooting plenty of black-and-white on a budget.$en$ WHERE slug = 'aristaedu200' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A black-and-white film that Freestyle in the US sells as a rebrand of Czech maker Foma's Fomapan 400. The emulsion is the same as Fomapan 400, and it sells for less in North America. Great for shooting plenty of black-and-white on a budget.$en$ WHERE slug = 'aristaedu400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$An ultra-slow ISO 13 black-and-white cinema film. Even in sunlight you'll need fairly long exposures, but the reward is smooth, nearly grainless tones and painterly gradation. A film for a tripod and a little patience.$en$ WHERE slug = 'babylonkino13' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A dual-emulsion black-and-white film from France's Bergger. Two layers of silver produce rich tonal gradation and deep, well-rendered shadows.$en$ WHERE slug = 'bergger400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A black-and-white film based on ORWO cinema stock. Deep gray gradations that call Berlin's streets to mind and a classic movie look define it. A good match when you want to capture a city's atmosphere in a single frame.$en$ WHERE slug = 'berlinkino400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A black-and-white film processed in standard C-41 color chemistry. Because any regular color lab could develop it, it was an easy way into black-and-white. Discontinued in 2014.$en$ WHERE slug = 'bw400cn' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Fujifilm's most affordable color negative. Lively greens and teals plus a very friendly price keep it in steady use for everyday snapshots.$en$ WHERE slug = 'c200' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A color negative from the UK's Candido Collective. It's made from Kodak Vision3 250D motion picture film with the remjet removed, so any regular C-41 lab can process it. Daylight balanced, it's an easy choice for shooting during the day.$en$ WHERE slug = 'candido400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Daylight balanced, with fine, clean grain and natural color in sunlight. This line comes from Chinese OEM factories that cut Kodak Vision3 family motion picture film, strip the remjet, and respool it into 36-exposure 35mm cassettes. In Korea it goes by a nickname that means "Chinese CineStill." Since it's a generic name rather than an official brand, color and quality can vary from batch to batch. There's no DX code, so you have to set the ISO manually, and any regular C-41 lab can develop it.$en$ WHERE slug = 'chinesecinestill100d' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Tungsten balanced, it renders calm, restrained color in scenes lit mainly by artificial light, like interiors and stages. This line comes from Chinese OEM factories that cut Kodak Vision3 family motion picture film, strip the remjet, and respool it into 36-exposure 35mm cassettes. In Korea it goes by a nickname that means "Chinese CineStill." Since it's a generic name rather than an official brand, color and quality can vary from batch to batch. There's no DX code, so you have to set the ISO manually, and any regular C-41 lab can develop it.$en$ WHERE slug = 'chinesecinestill320t' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Daylight balanced, with an all-around look that copes with everything from bright sun to overcast skies. This line comes from Chinese OEM factories that cut Kodak Vision3 family motion picture film, strip the remjet, and respool it into 36-exposure 35mm cassettes. In Korea it goes by a nickname that means "Chinese CineStill." Since it's a generic name rather than an official brand, color and quality can vary from batch to batch. There's no DX code, so you have to set the ISO manually, and any regular C-41 lab can develop it.$en$ WHERE slug = 'chinesecinestill400d' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A fast, tungsten-balanced film that comes alive in low light full of artificial sources, like night streets and city skylines. This line comes from Chinese OEM factories that cut Kodak Vision3 family motion picture film, strip the remjet, and respool it into 36-exposure 35mm cassettes. In Korea it goes by a nickname that means "Chinese CineStill." Since it's a generic name rather than an official brand, color and quality can vary from batch to batch. There's no DX code, so you have to set the ISO manually, and any regular C-41 lab can develop it.$en$ WHERE slug = 'chinesecinestill800t' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$CineStill's everyday film, launched in 2022. Faster than 50D and more natural in color than 800T, it's the one to grab when you want to bring a cinematic look to ordinary scenes.$en$ WHERE slug = 'cinestill400d' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$CineStill's daylight motion picture film, converted into a color negative. Its low ISO 50 speed and rich color detail make it especially well suited to sunny daytime scenes.$en$ WHERE slug = 'cinestill50d' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A film known for cinematic, tungsten-balanced color and strong halation around highlights. It looks great on night streets and in city lights after dark.$en$ WHERE slug = 'cinestill800t' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$CineStill's black-and-white film. Based on Kodak Eastman Double-X 5222, its gritty grain and deep contrast create a cinematic mood. Any regular black-and-white lab can process it.$en$ WHERE slug = 'cinestillxx' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The most affordable color film around. Its low saturation and soft tones turn out surprisingly good results on overcast days and under indoor lighting.$en$ WHERE slug = 'colorplus200' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The finest, most precise grain in the Delta line. Built on T-grain technology, it's a go-to when you want smooth black-and-white for landscapes, portraits, and still lifes. It sits in roughly the same spot as Fujifilm Acros II.$en$ WHERE slug = 'delta100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A professional high-speed black-and-white film that takes pushing well. Its true native speed is around ISO 1000 to 1600, but it's labeled 3200 as a fast film, and it shows up often in low light: night streets, concerts, and documentary work.$en$ WHERE slug = 'delta3200' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The Delta series is Ilford's T-grain (modern grain) black-and-white line. With finer grain and more refined tones than HP5, it's the pick for clean monochrome in city photography and portraits.$en$ WHERE slug = 'delta400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Kodak's classic black-and-white motion picture film. Better known by its code number, 5222, it has deep contrast and gritty grain, which makes it the one to reach for when you want the feel of a black-and-white movie in your stills.$en$ WHERE slug = 'doublex' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Kodak's vivid slide film, introduced in 1999 and discontinued in 2012. ISO 100, E-6 process. The VS stands for "Vividly Saturated," and it was designed for subjects that suit strong color, like nature, landscapes, and food.$en$ WHERE slug = 'e100vs' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Lomography's entry-level black-and-white film. Reportedly based on Foma stock, its fine grain and calm tones make it a good place to start shooting everyday black-and-white.$en$ WHERE slug = 'earlgrey100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Kodak's slide film, a classic revived in 2018. Cool tones and honest color are its signature, and it remains a steady choice for slide projection and film scanning workflows.$en$ WHERE slug = 'ektachrome100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$An ISO 200 slide film from the Kodak Professional line. It held up well to pushing (+1 to +3 stops), so it was often used in low light, in the studio, and under artificial light, and its calm tones and fine grain won it fans. Discontinued in 2012.$en$ WHERE slug = 'ektachromeE200' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A high-saturation color negative from the Kodak Professional line. Rich saturation and microfine grain make it a frequent choice for landscape and travel photography when you want color close to slide film.$en$ WHERE slug = 'ektar100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Fujifilm's daylight color negative motion picture film. Soft color and rich shadow detail kept it in steady use for documentaries and independent films. It was discontinued when Fuji left the motion picture film business in 2018.$en$ WHERE slug = 'eterna250d' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Fujifilm's tungsten color negative motion picture film. It offered fast speed and calm color for night and indoor shooting, but was discontinued in 2018 when Fuji ended its motion picture film business. You'll still come across it now and then on the vintage market.$en$ WHERE slug = 'eterna500t' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A revival film from Italy's Ferrania. A descendant of the cinema stock used in Fellini's films of the 1960s, it's known for strong contrast, deep blacks, and fine grain with a lively silvery quality. The results look like a frame from a black-and-white movie.$en$ WHERE slug = 'ferraniap30' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The first color negative from Malaysia's FilmNeverDie, released in 2018. True to its name ("iro" means color), it sold out quickly in Australian and Asian markets. It's discontinued now, but it's where the IRO line's identity began.$en$ WHERE slug = 'fndiro200' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The second edition of the IRO series. With 39 exposures per roll, crisp, saturated color, and soft grain, it comes up often for natural-light snapshots and street photography. C-41.$en$ WHERE slug = 'fndiro400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$True to its name ("kiro" means yellow), this 27-exposure film leans toward warm tones. A sibling to IRO, it's a daylight film that renders midday sun even more golden. C-41.$en$ WHERE slug = 'fndkiro400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$"Kumo" means cloud. This daylight ECN-2 film is original Kodak Vision3 5207 (250D) motion picture stock, simply respooled. The remjet is left on, so ECN-2 development is the proper route, and it's the closest you'll get to a daytime cinema look.$en$ WHERE slug = 'fndkumo250d' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$True to its name ("sora" means sky), this ISO 200, 36-exposure color negative takes to daylight beautifully. Fresh, airy tones and even grain make it a good fit for landscape and travel photography. C-41.$en$ WHERE slug = 'fndsora200' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$"Umi" means sea. This ISO 800, 36-exposure film is tuned for night and low light, capturing bluish tones and rich shadows, and it comes up often for city-at-night reportage. C-41.$en$ WHERE slug = 'fndumi800' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A slow black-and-white film from Czech maker Foma. Its ISO 100 classic cubic-crystal emulsion is known for gritty grain and deep shadows, making it a strong choice when you're after a vintage monochrome mood.$en$ WHERE slug = 'fomapan100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$An ISO 200 black-and-white negative from Czech maker Foma. Fomapan 200 Creative is a panchromatic, medium-speed film aimed at fine grain, high resolving power, and crisp edge definition.$en$ WHERE slug = 'fomapan200' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Czech maker Foma's budget black-and-white film. Cheaper than HP5 Plus or Tri-X and coarser in grain, it suits documentary and experimental black-and-white work.$en$ WHERE slug = 'fomapan400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The daylight film from Fotocola, a cine-film respooling brand on the Korean market. Based on Kodak Vision3 250D and prepared for still photography, it can be processed at C-41 labs too.$en$ WHERE slug = 'fotocola250d' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Fotocola's tungsten film. Based on Kodak Vision3 500T, it gives a cinematic look at night and indoors.$en$ WHERE slug = 'fotocola500t' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Ilford's medium-speed black-and-white film. Rich grays and clean grain define it, and it's a traditional workhorse for landscapes, still lifes, and medium format work.$en$ WHERE slug = 'fp4plus' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The softest-toned portrait film in Fujifilm's slide lineup. Natural skin tones and restrained saturation kept it in steady use for fashion and weddings. Discontinued in 2011.$en$ WHERE slug = 'fujiastia100f' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The ISO 100 everyday color negative in Fujifilm's Fujicolor line. A slow film that suits bright days and travel snapshots, it's known for clear, calm color and fine grain. Along with Fujifilm 200 and 400, it's an easy pick from the core color lineup.$en$ WHERE slug = 'fujifilm100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Fuji's everyday ISO 200 color negative, now sold again in a simple box design. Easygoing contrast and clean tones define it, and it's the film most often recommended for everyday snapshots.$en$ WHERE slug = 'fujifilm200' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Fuji's everyday ISO 400 color negative, relaunched in 2022 in a simple box design. Warm tones, natural grain, and wide latitude let you use it in anything from sunshine to overcast skies. It belongs to the same series as Fujifilm 200 and 800.$en$ WHERE slug = 'fujifilm400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A high-speed black-and-white film Fujifilm introduced in the 1990s. Its ISO 1600 gritty grain and punchy contrast made it a regular for night and indoor news photography. Discontinued around 2010.$en$ WHERE slug = 'fujineopan1600' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Fujifilm's everyday black-and-white film. Its fine, clean grain helped shape the feel of Japanese black-and-white photography. Discontinued in 2013, it's mentioned alongside Acros II more often than any other Japanese black-and-white film.$en$ WHERE slug = 'fujineopan400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$An everyday roll released in 1959 that became the standard Japanese black-and-white film. Fine ISO 100 grain and forgiving exposure latitude kept it in long use in photo studios and student darkrooms. Discontinued around 2009.$en$ WHERE slug = 'fujineopanss' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Fujifilm's professional color negative. Its soft pastel tones made it the standard for portrait and wedding photography. Prices shot up after its discontinuation was announced in 2021, and it's one of the most talked-about films on the vintage and collector market.$en$ WHERE slug = 'fujipro400h' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$An older high-speed color negative from Fujifilm. At ISO 1600, it was made to cover dark settings like indoor parties and stage shows in a single roll. It's discontinued now and hard to find.$en$ WHERE slug = 'fujisuperhg1600' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A calmer slide film released separately from Velvia 100. Its saturation falls between Velvia 50 and 100, and its more natural tones meant it was used for city scenes and portraits as well as landscapes. Discontinued in the mid-2010s.$en$ WHERE slug = 'fujivelvia100f' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A film that captures everyday life with a nostalgic, warm golden glow. Its results are dependable for the price, which is why it's the film people pick up most when they start shooting film.$en$ WHERE slug = 'gold200' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Shanghai Film's longest-running black-and-white film. Its gritty grain and punchy contrast are often put to work on cityscapes and documentary photography, and having been discontinued and revived more than once, it's a classic of Chinese black-and-white film.$en$ WHERE slug = 'gp3100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The faster sibling in the GP3 series. Its ISO 400 gritty grain sees frequent use in night and indoor reportage, and it's fairly forgiving when pushed.$en$ WHERE slug = 'gp3400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$An ISO 400 panchromatic black-and-white negative branded for Holga cameras. Reportedly supplied by Foma, its gritty grain and plain, unfussy tones pair well with the loose rendering of a toy camera.$en$ WHERE slug = 'holga400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A classic black-and-white film with wide development latitude and rich grays. It's the first film that comes to mind for documentary and street photography.$en$ WHERE slug = 'hp5plus' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A color negative carrying the Ilford name, best known for black-and-white. It's now sold as Ilfocolor Vintage Tone 400 Plus. The color leans slightly toward cyan, so greens and blues are subdued while reds and yellows stand out, and true to the name, it's described as giving the look of old photographs. C-41 process, daylight balanced, 35mm in 24 and 36 exposures.$en$ WHERE slug = 'ilfocolor400plus' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Ilford's student and budget black-and-white film. Made in the same factory as Kentmere Pan, it has soft tones, moderate contrast, and big grain. At its easy price, it's a film we recommend for getting started in black-and-white.$en$ WHERE slug = 'ilfordpan100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The ISO 100 film in Fujifilm's Japanese industrial line. It sits in a similar spot to Pro Image 100, known for stable storage and warm color.$en$ WHERE slug = 'industrial100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The ISO 400 film in the Industrial line. A cousin of Pro 400H, it was widely used for industrial and portrait photography in Japan. Sold only in Japan.$en$ WHERE slug = 'industrial400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Japan Camera Hunter's own-brand black-and-white film. Strong contrast, gritty grain, and extended red sensitivity have made it a cult film for street photography.$en$ WHERE slug = 'jchstreetpan400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Kentmere's entry-level ISO 100 black-and-white film. Cheaper than Ilford Delta 100 or FP4, yet fine and calm in grain, it's often recommended as a starter for black-and-white landscapes and still lifes.$en$ WHERE slug = 'kentmere100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Kentmere's new emulsion, released in 2024. A medium speed between Pan 100 and Pan 400 makes it a balanced black-and-white film that handles landscapes, everyday scenes, and portraits with ease.$en$ WHERE slug = 'kentmere200' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$An entry-level black-and-white film known as a line from an Ilford subsidiary. It costs less than HP5 or Delta, yet the results are reliably solid, which is why it's recommended to people picking up black-and-white for the first time.$en$ WHERE slug = 'kentmere400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Kodak's revived low-speed daylight color negative. It is often compared to Pro Image 100 for its natural color, but it reads a little calmer and more neutral, so it is safer to treat it as a film of its own.$en$ WHERE slug = 'kodacolor100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A mid-speed everyday color negative. It has a different personality from Gold 200 and is better thought of as a cousin of ColorPlus 200, with soft, easygoing color.$en$ WHERE slug = 'kodacolor200' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Kodak's color reversal stock for motion pictures, shipped under the 35mm cine catalog code 5294. It belongs to the daylight-balanced ISO 100 E-6 slide lineup, with deep saturation and fine grain in natural light and outdoor work, and it still turns up now and then on short films and music videos.$en$ WHERE slug = 'kodake100d5294' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Konica's standard ISO 100 color negative. The finest-grained film in the Centuria line, it was a frequent pick for landscapes and travel. Discontinued around 2006.$en$ WHERE slug = 'konicacenturia100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The mid-speed member of Konica's Centuria line. Warm color and balanced contrast kept it in steady use for everyday photos. Discontinued in 2006.$en$ WHERE slug = 'konicacenturia200' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Konica's everyday color negative. Through the 2000s it was a steady, good-value choice for photographers in Korea, until Konica left the photo business and the film was discontinued around 2006.$en$ WHERE slug = 'konicacenturia400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$An ISO 100 color negative Konica sold in Japan as a professional-use (gyomuyo) film. It is known for near-neutral color and tidy grain, and it is said to handle EIs anywhere from 50 to 80 well, giving it generous latitude. Discontinued.$en$ WHERE slug = 'konicaindustrial100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The ISO 400 sibling of Earl Grey. Bold grain and deep contrast make it a good match for black-and-white street and portrait work.$en$ WHERE slug = 'ladygrey400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A warm-toned color negative Lomography released in 2025. It aims for natural skin tones and a classic analog look that suits everyday shooting. ISO 200, standard C-41 processing.$en$ WHERE slug = 'lomoclassicolor200' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Lomography's fine-grained everyday color film. Its color holds steady in bright outdoor sun, which is why it often gets recommended to beginners.$en$ WHERE slug = 'lomocolor100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Lomography's everyday color film. Lomography doesn't make it in-house, so the base stock has changed over the years and results vary, but that unpredictability is part of the Lomo charm.$en$ WHERE slug = 'lomocolor400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Lomography's high-speed everyday color film. It is strong indoors and after sunset, and its heavy grain becomes part of the look on purpose.$en$ WHERE slug = 'lomocolor800' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Released in 2023, this color negative sets out to recreate the look of 1990s movies, with rich grain, deep blues, vivid reds and clear yellows. Standard C-41 processing. The canister has no DX code printed on it, so you'll need to set the ISO by hand.$en$ WHERE slug = 'lomocolor92' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A color film that pulls saturation down and pushes contrast up for an urban mood. It suited the grayish city scenes of the pandemic years and became a hit almost overnight.$en$ WHERE slug = 'lomometropolis' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A color-shift film that turns greens purple and blues teal. It develops in C-41, and the dreamy, unreal results make it a regular in experimental photography.$en$ WHERE slug = 'lomopurple' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Lomography's redscale color film. The film is exposed through the back side of a regular color stock, so reds and yellows come through strongly. You can expose anywhere in the ISO 50 to 200 range.$en$ WHERE slug = 'lomoredscale' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A color negative whose colors shift toward a strong turquoise depending on speed and exposure. Part of the LomoChrome series alongside Purple and Metropolis, it can be shot freely anywhere from ISO 100 to 400.$en$ WHERE slug = 'lomoturquoise' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The first color line from China's Lucky since its color negative, discontinued in 2012, came back in the first half of 2025. ISO 200, standard C-41 processing. Expect neutral tones with a slight red cast, fine grain and punchy contrast. Released in both 35mm and 120.$en$ WHERE slug = 'luckycolor200' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$An inexpensive black-and-white film made by Lucky Group Corporation in Hebei, China. The improved New version from 2017 has soft tonality, and its weak antihalation layer lets a faint glow form around highlights, which gives it a look of its own. Standard development in Kodak D-76.$en$ WHERE slug = 'luckyshd100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Lucky's ISO 400 black-and-white film from China. Produced with Kodak's cooperation in the early 2000s, the line was discontinued in 2012 and revived in March 2024. Wide exposure latitude and good grain detail make it easy to work with outdoors or in the studio. Standard development in D-76, with a slight underrating to EI 200 recommended.$en$ WHERE slug = 'luckyshd400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Leica's first black-and-white film, released in 2025. ISO 50, with ultra-high resolution of 280 lp/mm and super-panchromatic sensitivity reaching 780nm. It shows what it can really do on a sunny day paired with a fast lens.$en$ WHERE slug = 'monopan50' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Fujifilm's ISO 1600 high-speed color film. It was sold only in Japan and was strong in low light and indoor portraits, and since its discontinuation it has become a cult film whose price has climbed steeply on the collector market.$en$ WHERE slug = 'natura1600' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A C-41 color negative coated by InovisCoat in Germany, using the Wolfen NC200 emulsion. Unlike its NC-family siblings NC400 and NC500, it has an orange base, which makes scanning easier. It is known for natural color and crisp contrast, with greens and reds that are said to come out well. Skin tones lean slightly warm, so it handles portraits fine too. Daylight balanced, 35mm, 36 exposures.$en$ WHERE slug = 'opticolour200' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Black-and-white film made for the Japanese market by Harman (the same UK factory as Ilford). It launched in 2016 alongside the ISO 400 version as an entry-level, student-friendly line, and is known for its reasonable price. Made in the UK, distributed in Japan.$en$ WHERE slug = 'orientalseagull100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The faster member of the black-and-white line Harman (the same UK factory as Ilford) makes for the Japanese market. It is the 400 version of the entry-level, student-friendly line launched in 2016 alongside ISO 100, and the extra stop of speed lets you shoot freely indoors and in low light. Made in the UK, distributed in Japan.$en$ WHERE slug = 'orientalseagull400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$An orthochromatic black-and-white film that doesn't respond to red. In portraits, lips and skin go dark, but in still life, landscape and copy work it gives deep blue skies and solid tones. It can also be handled in the darkroom under a red safelight, which is a nice bonus.$en$ WHERE slug = 'orthoplus80' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A 400 ISO black-and-white film from ORWO in Germany. A successor to the NP15 family from the East German era, it is known for heavy contrast and rough grain, and it fits documentary and street work when you want a strong impression.$en$ WHERE slug = 'orwon75' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$ORWO's 100 ISO black-and-white cinema film. Fine grain, a rich range of grays and clean tones make it a good choice when you want smooth, film-like black and white. It is also the base film for Berlin Kino and Potsdam Kino.$en$ WHERE slug = 'orwoun54' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Ilford's slowest black-and-white film. Its low ISO 50 speed brings extremely fine, precise grain and rich tonal gradation, which makes it hard to beat for landscapes in strong sunlight, still life and copy work.$en$ WHERE slug = 'panfplus50' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The improved second generation of Phoenix, released in 2024. It keeps the bold grain and red tones of the original while widening the latitude, so it is easier to handle. It is the only color negative line made in Britain, at the Ilford factory.$en$ WHERE slug = 'phoenix2' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The first color film from black-and-white maker Harman, released in 2023. Strong contrast, a red base and rough grain make it the first film that comes to mind when you're after experimental color.$en$ WHERE slug = 'phoenix200' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The softest-toned film in the Portra family. Low saturation and rich detail made it the standard for natural-light portraits and weddings. It does especially well outdoors in strong sun.$en$ WHERE slug = 'portra160' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The Natural Color line of the first-generation Portra, released in 1998. Low saturation and soft skin tones made it a go-to for weddings and portraits. Discontinued in 2010 and folded into the current Portra line.$en$ WHERE slug = 'portra160nc' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The Vivid Color line of the first-generation Portra. More saturated and crisper in color than NC, it was a frequent pick for advertising and fashion shoots. Discontinued in 2010.$en$ WHERE slug = 'portra160vc' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The name that stands for professional color negative film. Soft skin tones and wide latitude made it the standard for portraits, weddings and documentary work.$en$ WHERE slug = 'portra400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The ISO 400 Natural Color of the first-generation Portra, and the line most often named as the standard color film for portraits and weddings. Discontinued in 2010 and folded into the current Portra 400.$en$ WHERE slug = 'portra400nc' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The Vivid Color variant of Portra 400. Shooters reached for its stronger saturation when they wanted deeper color in everyday photos. Discontinued in 2010.$en$ WHERE slug = 'portra400vc' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The fastest film in the Portra series, and the first one to pull out for portraits indoors or in the evening. The grain is coarser, but the color is still soft in true Portra fashion.$en$ WHERE slug = 'portra800' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A low-speed black-and-white film based on ORWO cinema stock. Fine grain and soft midtones let it capture landscapes and still life with the detail of a classic movie.$en$ WHERE slug = 'potsdamkino100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A sibling of Kodak ProImage 100, sold in Mexico, Latin America and parts of Asia. Recommended for wedding and portrait work, it often came up as an alternative to Portra. Now discontinued.$en$ WHERE slug = 'profotoxl100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A color negative Kodak made for markets with hot climates. Good storage stability and appealing warm tones have earned it a reputation as a good-value film for everyday shooting and travel.$en$ WHERE slug = 'proimage100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Often named the most natural-looking of Fujifilm's slide films. It is less saturated than Velvia, so it is easy to use for portraits and city photos too.$en$ WHERE slug = 'provia100f' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A color negative Fujifilm released in the late 1990s. On top of the usual three RGB layers, it added a fourth cyan-sensitive layer, which let it render color accurately even under artificial light. Discontinued in 2013, it still trades on the vintage market.$en$ WHERE slug = 'reala100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A daylight color negative Fujifilm made for motion pictures. Its fast ISO 500 speed and 4th Color Layer technology keep color rendering steady even in tricky mixed light. The proper process is ECN-2, and it is now a discontinued vintage cinema stock.$en$ WHERE slug = 'reala500d' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Fujifilm's new professional ISO 100 color negative, released in 2024 for the Korean and Japanese markets only. It carries on the fourth color layer structure of the original Reala, with rich color, soft tones and fine grain. A rare treat we'd recommend for portraits and still life.$en$ WHERE slug = 'realaace100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Vision3 5207 with only the remjet removed, respooled at its native ISO 250. Without a push, the grain stays orderly and the highlights hold up, making it a daylight film well suited to natural-light portraits and everyday shooting. C-41.$en$ WHERE slug = 'reflxlab250d' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Kodak's newly released 5207 with AHU (anti-halation undercoat) treatment, respooled at ISO 320. With no remjet and no halation, it gives you a Portra 400-like feel through C-41.$en$ WHERE slug = 'reflxlab320d' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Vision3 5207 (250D) with the remjet removed, pushed one stop and respooled as an ISO 400 daylight film. Residual halation softly wraps bright midday light. C-41.$en$ WHERE slug = 'reflxlab400d' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Kodak Vision3 5219 (500T) with the remjet stripped by Shenzhen's Reflx Lab, pushed to ISO 800 and respooled. It often comes up as the cheapest way to get a cinematic look on night streets and under tungsten light. C-41.$en$ WHERE slug = 'reflxlab800t' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The sibling of Glow. It comes in the same short 27-exposure roll and renders harsh midday light cool, with bluish tones and rough grain. C-41.$en$ WHERE slug = 'retoaqua400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$An ISO 400 color negative released in 2023 by Reto of Hong Kong. It comes in a short 27-exposure roll, and its faded warm tones and low contrast turn city afternoons into something cinematic. C-41.$en$ WHERE slug = 'retoglow400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The crispest film in the Reto lineup. 36 exposures, fine grain, medium-to-high contrast and lively saturation give clear everyday color rather than a vintage look. C-41.$en$ WHERE slug = 'retoprism400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The ISO 400 sibling of Retro 80S. It combines extended IR sensitivity with a faster speed, for when you want to grab IR effects quickly in street and travel photography.$en$ WHERE slug = 'rolleiretro400s' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Rollei's black-and-white film with extended infrared sensitivity. Paired with a 720nm IR filter, it gives the IR look of white leaves and black skies. Rich tones and fine grain.$en$ WHERE slug = 'rolleiretro80s' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Rollei's traditional black-and-white line. Classic grain and soft tonal gradation suit a straightforward, old-school black-and-white mood.$en$ WHERE slug = 'rpx100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The ISO 400 member of the RPX line. Rough grain and strong contrast suit documentary and street work, and it often comes up as a European alternative to HP5 Plus.$en$ WHERE slug = 'rpx400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A black-and-white film with sensitivity extended into red and near-infrared. Paired with a 720nm infrared filter, it produces the IR look of white leaves and black skies. A specialty film that any regular black-and-white lab can process.$en$ WHERE slug = 'sfx200' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$An everyday color film with Fujifilm's signature teals and greens. If you like cooler tones over Kodak-style warmth, it is one you'll keep coming back to.$en$ WHERE slug = 'superia400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A premium line from Fujifilm's Japanese market. Part of the Superia 400 family, but with a step more refined color and finer grain, it saw steady use for portraits and everyday photos. Discontinued in 2024.$en$ WHERE slug = 'superiapremium400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A high-speed color film Fujifilm sold only in Japan. Its soft skin tones won it a devoted following among portrait shooters, and it still comes up often on the vintage market after its discontinuation.$en$ WHERE slug = 'superiavenus800' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The slower sibling of T-Max 400. At ISO 100 it has the finest, most precise grain in the line, making it a strong black-and-white choice for fashion, still life and big enlargements. The exact opposite direction from the grit of Tri-X.$en$ WHERE slug = 'tmax100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$T-Max is Kodak's modern black-and-white line. Finer grain and smoother tones than Tri-X make it the one to reach for when you want refined black and white, and it is used widely for fashion, still life and landscapes.$en$ WHERE slug = 'tmax400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Kodak's high-speed black-and-white film. Its true native speed is around 800 to 1000, but it was designed to be pushed to P3200. Discontinued in 2012 and revived in 2018.$en$ WHERE slug = 'tmaxp3200' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The black-and-white film that became a symbol in photographic history. Its rough grain and deep contrast shaped the look of photojournalism and documentary work.$en$ WHERE slug = 'trix400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$An inexpensive color negative from Tudor Photography in the UK. It is said to be rebranded Fujifilm stock from Japan, and it develops in C-41. An everyday color film you can shoot freely without worrying about the cost.$en$ WHERE slug = 'tudorxlx100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$An inexpensive color negative from Tudor Photography in the UK. It is said to be rebranded Fujifilm stock from Japan, and it develops in C-41. An easygoing everyday color film for carefree snapshots.$en$ WHERE slug = 'tudorxlx200' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The front-runner among everyday color films. Rich saturation and soft grain give daily life a warm look, and it does especially well in sunlight.$en$ WHERE slug = 'ultramax' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The one-stop-faster sibling of Velvia 50. It keeps the deep saturation, and ISO 100 makes handheld shooting a little easier, so it often gets used beyond landscapes, for street and portraits too.$en$ WHERE slug = 'velvia100' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Fujifilm's flagship slide film. Its intensely saturated greens and reds made it a legend in landscape photography. At a slow ISO 50, a tripod is close to essential.$en$ WHERE slug = 'velvia50' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The daylight-balanced line of the motion picture color negative Kodak produces today. The proper process is ECN-2, and with its rem-jet backing intact, it delivers rich detail and accurate cinematic tones.$en$ WHERE slug = 'vision250d' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Vision3 250D dressed up for still photography. It keeps the AHU (anti-halation undercoat) backing, so halation stays restrained and the tones run deep like a movie. A big plus is that some labs will also process it in C-41.$en$ WHERE slug = 'vision250dahu' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The standard 200T tungsten stock on Hollywood film sets. ECN-2 is the proper route, but with the remjet removed it can also go through C-41, and it carries night street light over with a cinematic look. CineStill 200T is a C-41 respool of this film.$en$ WHERE slug = 'vision3200t' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Kodak's tungsten color negative for motion pictures. Its fast ISO 500 speed makes it the standard for night streets and interiors, and ECN-2 is the proper process. It is also known as the source film for CineStill 800T.$en$ WHERE slug = 'vision500t' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$Vision3 500T dressed up for still photography. Strong under tungsten light, it has a nighttime movie look with restrained halation. Next to the strong red halation of CineStill 800T, the mood is noticeably calmer.$en$ WHERE slug = 'vision500tahu' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The sibling of NC500. From the same East German motion picture emulsion lineage, it is a color negative rated one stop lower at ISO 400. Its rough grain and rich tones often come up in natural-light street photography.$en$ WHERE slug = 'wolfennc400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$ORWO's color negative cinema film, revived in 2023. Its cinematic teal shadows and warm highlights make a strong impression. ECN-2 processing is the original recommendation, but it can also go through standard C-41, which makes it a good way to bring a cine look into everyday photos.$en$ WHERE slug = 'wolfennc500' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A black-and-white film that develops in C-41 (the color process), which makes it unusual. Any regular color lab can process it, so it lowers the barrier to black-and-white work considerably.$en$ WHERE slug = 'xp2super' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$The ISO 400 black and white from Yashica's MF-1 line. Its strong contrast is said to suit street snapshots.$en$ WHERE slug = 'yashicabw400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$An ISO 400 color negative Yashica brought back alongside the MF-1 camera. Warm-leaning tones and soft grain suit portraits and everyday snapshots. C-41.$en$ WHERE slug = 'yashicacolor400' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$A limited-edition ISO 400 color film from Yashica. Aiming for an '80s feel, it has heavily boosted saturation and strong grain, and it shows up often in natural-light everyday snapshots. C-41.$en$ WHERE slug = 'yashicagolden80s' AND description_en IS NULL;
UPDATE public.films SET description_en = $en$An ISO 400 color negative from Malaysia's FilmNeverDie, made in collaboration with photographer Mr. Negative. Its "faded horror" look, with saturation drained and grain kept crisp, has made it popular with collectors in Japan and Southeast Asia. C-41.$en$ WHERE slug = 'zombie400' AND description_en IS NULL;

-- 현상소 96곳 (name·region 원문으로 찾는다)
UPDATE public.labs SET name_en = COALESCE(name_en, $en$Gallery Photo Studio$en$), address_en = COALESCE(address_en, $en$1F, Samsung Bldg., 642 Samseong-ro, Gangnam-gu, Seoul$en$), features_en = COALESCE(features_en, $en$High-resolution option (up to 3600×5400).
Scan only: 3,000 won per roll. Development adds 4,000 won per roll.$en$) WHERE name = '갤러리사진관' AND region = '서울';
