UPDATE public.labs SET name_en = COALESCE(name_en, $en$Dalui Bada$en$), address_en = COALESCE(address_en, $en$Basement, 173 Jangmal-ro, Wonmi-gu, Bucheon-si, Gyeonggi-do$en$), features_en = COALESCE(features_en, $en$Photo studio and film lab.
Runs one-day classes in black-and-white darkroom printing.$en$) WHERE name = '달의바다' AND region = '경기';
UPDATE public.labs SET name_en = COALESCE(name_en, $en$Dongbu Color$en$), address_en = COALESCE(address_en, $en$81 Bonghwasan-ro, Jungnang-gu, Seoul$en$), features_en = COALESCE(features_en, NULL) WHERE name = '동부칼라' AND region = '서울';
UPDATE public.labs SET name_en = COALESCE(name_en, $en$Mangwoosamlim$en$), address_en = COALESCE(address_en, $en$3F and 4F, 108 Eulji-ro, Jung-gu, Seoul$en$), features_en = COALESCE(features_en, NULL) WHERE name = '망우삼림' AND region = '서울';
UPDATE public.labs SET name_en = COALESCE(name_en, $en$Myeonggwang Studio$en$), address_en = COALESCE(address_en, $en$2F, Baekma Bldg., 4 Nonhyeon-ro 17-gil, Seocho-gu, Seoul$en$), features_en = COALESCE(features_en, NULL) WHERE name = '명광스튜디오' AND region = '서울';
UPDATE public.labs SET name_en = COALESCE(name_en, $en$Mirim Photo Studio$en$), address_en = COALESCE(address_en, $en$1F, 21 Gwangnaru-ro 24-gil, Gwangjin-gu, Seoul (in front of Konkuk University's old main gate)$en$), features_en = COALESCE(features_en, $en$High-resolution scans when paying by cash or bank transfer.$en$) WHERE name = '미림사진관' AND region = '서울';
UPDATE public.labs SET name_en = COALESCE(name_en, $en$Bodabom$en$), address_en = COALESCE(address_en, $en$4F, Sophia House Bldg., 1 Supyo-ro, Jung-gu, Seoul$en$), features_en = COALESCE(features_en, $en$Imacon X5 drum scanning, development in dedicated B&W chemistry, premium development, and contact printing available.$en$) WHERE name = '보다봄' AND region = '서울';
UPDATE public.labs SET name_en = COALESCE(name_en, $en$Bugwang Photo Studio$en$), address_en = COALESCE(address_en, $en$1F, 30 Wangsaeng-ro 66beon-gil, Nam-gu, Ulsan$en$), features_en = COALESCE(features_en, $en$Film development and scanning (development only or scan only also available). Also operates as an ID photo studio.$en$) WHERE name = '부광사진관' AND region = '울산';
UPDATE public.labs SET name_en = COALESCE(name_en, $en$Seha Photo Lab$en$), address_en = COALESCE(address_en, $en$3F, 4 Paldal-ro 35-gil, Buk-gu, Daegu$en$), features_en = COALESCE(features_en, $en$C-41, ECN-2, and B&W film development and scanning. High-resolution scan: 5,000 won extra. TIFF scans for 120 B&W.$en$) WHERE name = '세하포토랩' AND region = '대구';
UPDATE public.labs SET name_en = COALESCE(name_en, $en$Scopy Hongdae$en$), address_en = COALESCE(address_en, $en$2F, Hongik Bldg., 17 Yanghwa-ro 18an-gil, Mapo-gu, Seoul$en$), features_en = COALESCE(features_en, NULL) WHERE name = '스코피 홍대' AND region = '서울';
UPDATE public.labs SET name_en = COALESCE(name_en, $en$Scopy Noryangjin$en$), address_en = COALESCE(address_en, $en$164 Jangseungbaegi-ro, Dongjak-gu, Seoul$en$), features_en = COALESCE(features_en, NULL) WHERE name = '스코피 노량진' AND region = '서울';
UPDATE public.labs SET name_en = COALESCE(name_en, $en$Sinsin Color$en$), address_en = COALESCE(address_en, $en$10 Nonhyeon-ro 151-gil, Gangnam-gu, Seoul$en$), features_en = COALESCE(features_en, $en$Choice of Noritsu or Fuji scanner.$en$) WHERE name = '신신칼라' AND region = '서울';
